BEGIN;CREATE TABLE IF NOT EXISTS public.mobile_push_devices(mobile_push_devices_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,organizations_id bigint NOT NULL REFERENCES public.organizations(organizations_id) ON DELETE CASCADE,organization_members_id bigint NOT NULL REFERENCES public.organization_members(organization_members_id) ON DELETE CASCADE,auth_user_id uuid NOT NULL,device_id uuid NOT NULL,platform text NOT NULL CHECK(platform IN('android','ios')),expo_push_token text NOT NULL,app_version text NULL,enabled boolean NOT NULL DEFAULT true,last_registered_at timestamptz NOT NULL DEFAULT now(),disabled_at timestamptz NULL,last_error text NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organizations_id,device_id));ALTER TABLE public.mobile_push_devices ADD COLUMN IF NOT EXISTS last_error text NULL;CREATE INDEX IF NOT EXISTS mobile_push_devices_enabled_member_idx ON public.mobile_push_devices(organizations_id,organization_members_id) WHERE enabled=true;ALTER TABLE public.mobile_push_devices ENABLE ROW LEVEL SECURITY;ALTER TABLE public.mobile_push_devices FORCE ROW LEVEL SECURITY;DROP POLICY IF EXISTS mobile_push_devices_service_all ON public.mobile_push_devices;CREATE POLICY mobile_push_devices_service_all ON public.mobile_push_devices FOR ALL TO service_role USING(true) WITH CHECK(true);REVOKE ALL ON public.mobile_push_devices FROM PUBLIC,anon,authenticated;GRANT SELECT,INSERT,UPDATE,DELETE ON public.mobile_push_devices TO service_role;ALTER TABLE public.conversation_messages ADD COLUMN IF NOT EXISTS mobile_push_sent_at timestamptz;
CREATE OR REPLACE FUNCTION public.mobile_register_push_device_r60(p_organizations_id bigint,p_device_id uuid,p_platform text,p_expo_push_token text,p_app_version text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE m bigint;id bigint;BEGIN m:=public.r60_require_actor(p_organizations_id,'whatsapp.view');IF p_device_id IS NULL OR p_platform NOT IN('android','ios') OR coalesce(p_expo_push_token,'') !~ '^(ExponentPushToken|ExpoPushToken)\\[[^]]+\\]$' THEN RAISE EXCEPTION 'mobile_push_registration_invalid';END IF;INSERT INTO public.mobile_push_devices(organizations_id,organization_members_id,auth_user_id,device_id,platform,expo_push_token,app_version,enabled,last_registered_at,disabled_at,updated_at) VALUES(p_organizations_id,m,auth.uid(),p_device_id,p_platform,p_expo_push_token,left(nullif(btrim(coalesce(p_app_version,'')),''),80),true,now(),NULL,now()) ON CONFLICT(organizations_id,device_id) DO UPDATE SET organization_members_id=excluded.organization_members_id,auth_user_id=excluded.auth_user_id,platform=excluded.platform,expo_push_token=excluded.expo_push_token,app_version=excluded.app_version,enabled=true,last_registered_at=now(),disabled_at=NULL,last_error=NULL,updated_at=now() RETURNING mobile_push_devices_id INTO id;RETURN jsonb_build_object('ok',true,'deviceId',id);END $$;
CREATE OR REPLACE FUNCTION public.mobile_disable_push_device_r60(p_organizations_id bigint,p_device_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE m bigint;cnt bigint;BEGIN m:=public.r60_require_actor(p_organizations_id,'whatsapp.view');UPDATE public.mobile_push_devices SET enabled=false,disabled_at=now(),updated_at=now() WHERE organizations_id=p_organizations_id AND organization_members_id=m AND device_id=p_device_id AND auth_user_id=auth.uid();GET DIAGNOSTICS cnt=ROW_COUNT;RETURN jsonb_build_object('ok',true,'disabled',cnt);END $$;REVOKE ALL ON FUNCTION public.mobile_register_push_device_r60(bigint,uuid,text,text,text) FROM PUBLIC,anon;REVOKE ALL ON FUNCTION public.mobile_disable_push_device_r60(bigint,uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.mobile_register_push_device_r60(bigint,uuid,text,text,text) TO authenticated;GRANT EXECUTE ON FUNCTION public.mobile_disable_push_device_r60(bigint,uuid) TO authenticated;COMMIT;
